
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_csk4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_csk4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.441270565803546e+01, 2.441433824205256e+01, 2.450812191540461e+01, 2.488911010141489e+01, 2.592686272824144e+01, 2.786502382667400e+01, 2.985109410876256e+01, 2.992879793335061e+01, 2.764831174978530e+01, 2.446537059814504e+01, 1.873335548493083e+01, 5.842593045420461e+00, 1.336076918016085e+00, 1.251633007321671e+00, 1.106997433254102e+00, 9.296010448703680e-01, 8.330429365822607e-01, 7.901147291166705e-01, 7.696551572394421e-01, 7.603885974794720e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


